import pandas as pd
import numpy as np

def clean(df):
    d = df.copy()
    for c in d.columns:
        if d[c].dtype == object:
            d[c] = d[c].astype(str).str.strip()
            d[c] = d[c].replace({'nan': np.nan, 'None': np.nan, '': np.nan})
    if 'species' in d.columns:
        d['species'] = d['species'].replace({'Adeile': 'Adelie'})
        d.loc[~d['species'].isin(['Adelie', 'Chinstrap', 'Gentoo']), 'species'] = np.nan
    if 'island' in d.columns:
        d.loc[~d['island'].isin(['Biscoe', 'Dream', 'Torgersen']), 'island'] = np.nan
    if 'sex' in d.columns:
        d['sex'] = d['sex'].str.lower()
        d.loc[~d['sex'].isin(['male', 'female']), 'sex'] = np.nan
    for c in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors='coerce')
    if 'body_mass_g' in d.columns:
        mask = d['body_mass_g'] > 6500
        d.loc[mask, 'body_mass_g'] = d.loc[mask, 'body_mass_g'] / 1000.0
        d.loc[(d['body_mass_g'] < 2500) | (d['body_mass_g'] > 6500), 'body_mass_g'] = np.nan
    d = d.drop_duplicates()
    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'body_mass_g'])
    out = d.groupby('species', dropna=True)['body_mass_g'].mean()
    return {str(k): float(v) for k, v in out.items()}
